import React, { useState } from 'react';
import { trackEvent } from '../../utils/telemetry';

export default function NewsletterForm() {
  const [email, setEmail] = useState('');
  const [websiteHp, setWebsiteHp] = useState('');
  const [loading, setLoading] = useState(false);
  const [statusMessage, setStatusMessage] = useState(null);
  const [promoCode, setPromoCode] = useState(null);
  const [error, setError] = useState(null);

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError(null);
    setStatusMessage(null);

    // Basic client validation
    if (!email || !email.includes('@')) {
      setError('Моля, въведете валиден имейл адрес.');
      return;
    }

    setLoading(true);

    try {
      const response = await fetch('/api/newsletter', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          email,
          website_hp: websiteHp,
          source: 'finansprotect_newsletter_widget'
        })
      });

      const data = await response.json();

      if (response.ok && data.success) {
        setStatusMessage(data.message || 'Вие се абонирахте успешно!');
        trackEvent('newsletter_subscribed', { email });
        if (data.promoCode) {
          setPromoCode(data.promoCode);
        }
        setEmail('');
      } else {
        setError(data.error || 'Възникна грешка при абонирането.');
      }
    } catch (err) {
      setError('Свързването със сървъра се провали. Опитайте отново.');
    } finally {
      setLoading(false);
    }
  };

  return (
    <section className="py-12 px-6 bg-slate-900/60 border-y border-slate-800">
      <div className="max-w-4xl mx-auto text-center">
        <div className="inline-block p-3 bg-primary-500/10 rounded-2xl mb-4 border border-primary-500/20">
          <svg className="w-8 h-8 text-primary-400 mx-auto" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M3 8l7.89 5.26a2 2 0 002.22 0L21 8M5 19h14a2 2 0 002-2V7a2 2 0 00-2-2H5a2 2 0 00-2 2v10a2 2 0 002 2z" />
          </svg>
        </div>
        <h2 className="text-2xl md:text-3xl font-bold text-white mb-2">
          Абонирайте се за Finans Protect Digest
        </h2>
        <p className="text-gray-400 text-sm md:text-base max-w-xl mx-auto mb-6">
          Получавайте първи актуализации за нови банкови бонуси, Wallester възможности и счетоводни автоматизации.
        </p>

        {statusMessage ? (
          <div className="bg-emerald-500/10 border border-emerald-500/30 rounded-xl p-6 max-w-lg mx-auto" role="status">
            <p className="text-emerald-400 font-semibold mb-2">{statusMessage}</p>
            {promoCode && (
              <div className="mt-3 p-3 bg-slate-800/80 rounded-lg border border-emerald-500/40 inline-block">
                <span className="text-gray-400 text-xs block mb-1">Вашият ексклузивен VIP промокод:</span>
                <code className="text-xl font-mono text-emerald-300 font-bold tracking-wider">{promoCode}</code>
              </div>
            )}
          </div>
        ) : (
          <form onSubmit={handleSubmit} className="max-w-lg mx-auto" noValidate>
            {/* Honeypot field (Point 27 spam prevention) */}
            <div className="hidden" aria-hidden="true">
              <input
                type="text"
                name="website_hp"
                tabIndex="-1"
                autoComplete="off"
                value={websiteHp}
                onChange={(e) => setWebsiteHp(e.target.value)}
              />
            </div>

            <div className="flex flex-col sm:flex-row gap-3">
              <div className="relative flex-1">
                <input
                  type="email"
                  value={email}
                  onChange={(e) => setEmail(e.target.value)}
                  placeholder="Въведете вашия служебен имейл..."
                  aria-label="Имейл адрес за бюлетин"
                  aria-invalid={!!error}
                  aria-describedby={error ? "newsletter-error" : undefined}
                  disabled={loading}
                  className={`w-full px-4 py-3.5 bg-slate-800 border ${
                    error ? 'border-red-500 focus:ring-red-500' : 'border-slate-700 focus:ring-primary-500'
                  } rounded-xl text-white placeholder-gray-500 focus:outline-none focus:ring-2 transition-all`}
                />
              </div>

              <button
                type="submit"
                disabled={loading}
                className="px-6 py-3.5 bg-primary-600 hover:bg-primary-500 text-white font-semibold rounded-xl transition-all shadow-md shadow-primary-600/30 flex items-center justify-center gap-2 disabled:opacity-50 cursor-pointer"
              >
                {loading ? (
                  <span className="inline-block animate-spin rounded-full h-5 w-5 border-2 border-white border-t-transparent" />
                ) : (
                  <>
                    <span>Абонирай се</span>
                    <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M14 5l7 7m0 0l-7 7m7-7H3" />
                    </svg>
                  </>
                )}
              </button>
            </div>

            {error && (
              <p id="newsletter-error" className="text-red-400 text-xs text-left mt-2 pl-1" role="alert">
                {error}
              </p>
            )}
          </form>
        )}
      </div>
    </section>
  );
}
