import React, { useState } from 'react';
import { motion } from 'framer-motion';
import { CheckCircle, AlertCircle, Loader2, Send, User, Mail, Phone, Building, MessageSquare, ShieldCheck } from 'lucide-react';
import { isValidBgPhone, normalizeBgPhone, identifyBgOperator, formatBgPhoneDisplay } from '../../utils/phoneValidator';
import { generateDeviceFingerprint } from '../../utils/securityFingerprint';
import { trackEvent } from '../../utils/telemetry';

const WEBHOOK_URL = import.meta.env.VITE_FP_LEAD_WEBHOOK_URL || 'http://100.83.83.8:5679/webhook/fp-lead';
const NAME_MIN_LENGTH = 2;
const EMAIL_REGEX = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

export default function LeadCaptureForm() {
  const [formData, setFormData] = useState({
    name: '',
    email: '',
    phone: '',
    company: '',
    message: '',
    website_hp: '', // Honeypot field (Point 27)
  });

  const [errors, setErrors] = useState({});
  const [status, setStatus] = useState('idle'); // 'idle' | 'submitting' | 'success' | 'error'
  const [errorMessage, setErrorMessage] = useState('');
  const [detectedOperator, setDetectedOperator] = useState(null);

  const handleChange = (e) => {
    const { name, value } = e.target;
    
    if (name === 'phone') {
      const formatted = formatBgPhoneDisplay(value);
      setFormData((prev) => ({ ...prev, phone: formatted }));
      if (isValidBgPhone(value)) {
        setDetectedOperator(identifyBgOperator(value));
      } else {
        setDetectedOperator(null);
      }
    } else {
      setFormData((prev) => ({ ...prev, [name]: value }));
    }

    if (errors[name]) {
      setErrors((prev) => ({ ...prev, [name]: '' }));
    }
  };

  const validate = () => {
    const newErrors = {};

    const cleanName = formData.name.trim();
    if (!cleanName || cleanName.length < NAME_MIN_LENGTH) {
      newErrors.name = 'Името трябва да съдържа поне 2 символа.';
    }

    const cleanEmail = formData.email.trim();
    if (!cleanEmail || !EMAIL_REGEX.test(cleanEmail)) {
      newErrors.email = 'Моля въведете валиден имейл адрес.';
    }

    if (!formData.phone || !isValidBgPhone(formData.phone)) {
      newErrors.phone = 'Моля въведете валиден български телефон (мобилен 0888... или стационарен 02..., 032...).';
    }

    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  const handleSubmit = async (e) => {
    e.preventDefault();

    // 1. Honeypot anti-spam check (Point 27)
    if (formData.website_hp) {
      console.warn('Spam bot honeypot triggered in LeadCaptureForm');
      setStatus('success');
      return;
    }

    // 2. Client submission rate limiter (max 1 per 10 sec) (Point 27)
    const lastSub = sessionStorage.getItem('fp_lead_last_sub');
    const now = Date.now();
    if (lastSub && now - parseInt(lastSub, 10) < 10000) {
      setStatus('error');
      setErrorMessage('Моля изчакайте няколко секунди преди да изпратите нова заявка.');
      return;
    }

    if (!validate()) {
      return;
    }

    setStatus('submitting');
    setErrorMessage('');

    const normalizedPhone = normalizeBgPhone(formData.phone);
    const operatorInfo = identifyBgOperator(formData.phone);

    const payload = {
      name: formData.name.trim(),
      email: formData.email.trim(),
      phone: normalizedPhone || formData.phone,
      operator: operatorInfo.operator,
      company: formData.company.trim(),
      message: formData.message.trim(),
      source: 'finansprotect_landing_form',
      url: typeof window !== 'undefined' ? window.location.href : 'https://cashflow.openbalancer.com',
      timestamp: new Date().toISOString(),
      securityFingerprint: generateDeviceFingerprint(),
    };

    // Save lead info for Calendly auto-fill (Bonus Value)
    try {
      localStorage.setItem('fp_lead_name', payload.name);
      localStorage.setItem('fp_lead_email', payload.email);
      localStorage.setItem('fp_lead_company', payload.company);
      sessionStorage.setItem('fp_lead_last_sub', String(now));
    } catch (err) {}

    try {
      const res = await fetch(WEBHOOK_URL, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify(payload),
      });

      const data = await res.json().catch(() => ({}));

      if (res.ok && data.ok !== false) {
        setStatus('success');
        trackEvent('lead_form_submitted', {
          name: payload.name,
          email: payload.email,
          company: payload.company
        });
        setFormData({
          name: '',
          email: '',
          phone: '',
          company: '',
          message: '',
          website_hp: '',
        });
        setDetectedOperator(null);
      } else {
        setStatus('error');
        setErrorMessage(data.error || 'Грешка при изпращане на заявката. Моля опитайте отново.');
      }
    } catch (err) {
      setStatus('error');
      setErrorMessage(err.message || 'Възникна мрежова грешка. Моля проверете връзката си и опитайте отново.');
    }
  };

  const handleReset = () => {
    setStatus('idle');
    setErrorMessage('');
    setErrors({});
  };

  return (
    <section className="py-16 px-6" id="lead-form">
      <div className="max-w-2xl mx-auto">
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          className="bg-dark-800/80 backdrop-blur-sm border border-dark-700 rounded-2xl p-8 shadow-xl"
        >
          <div className="text-center mb-8">
            <h2 className="text-3xl font-bold text-white mb-3">
              Свържете се с Finans Protect
            </h2>
            <p className="text-gray-400 text-sm max-w-lg mx-auto">
              Оставете вашите данни за безплатна консултация относно Wallester Business картите и финансова автоматизация.
            </p>
          </div>

          {status === 'success' ? (
            <motion.div
              initial={{ scale: 0.95, opacity: 0 }}
              animate={{ scale: 1, opacity: 1 }}
              className="bg-green-500/10 border border-green-500/30 rounded-2xl p-8 text-center space-y-4"
              role="status"
              aria-live="polite"
            >
              <div className="flex justify-center">
                <CheckCircle className="w-16 h-16 text-green-400 animate-bounce" />
              </div>
              <h3 className="text-2xl font-bold text-green-400">
                Заявката е изпратена успешно!
              </h3>
              <p className="text-gray-300 text-sm max-w-md mx-auto">
                Благодарим ви! Данните ви са регистрирани успешно. Нашият екип ще се свърже с вас възможно най-скоро.
              </p>
              <button
                type="button"
                onClick={handleReset}
                className="mt-4 px-6 py-2.5 bg-green-500/20 hover:bg-green-500/30 text-green-300 font-semibold rounded-xl border border-green-500/40 transition-all text-sm cursor-pointer"
              >
                Изпрати нова заявка
              </button>
            </motion.div>
          ) : (
            <form onSubmit={handleSubmit} className="space-y-5" noValidate>
              {/* Honeypot hidden input (Point 27 spam prevention) */}
              <div className="hidden" aria-hidden="true">
                <input
                  type="text"
                  name="website_hp"
                  tabIndex="-1"
                  autoComplete="off"
                  value={formData.website_hp}
                  onChange={handleChange}
                />
              </div>

              {status === 'error' && (
                <motion.div
                  initial={{ opacity: 0, y: -10 }}
                  animate={{ opacity: 1, y: 0 }}
                  className="bg-red-500/10 border border-red-500/30 rounded-xl p-4 flex items-start justify-between text-red-400 space-x-3"
                  role="alert"
                >
                  <div className="flex items-start space-x-3">
                    <AlertCircle className="w-5 h-5 flex-shrink-0 mt-0.5" />
                    <span className="text-sm">{errorMessage}</span>
                  </div>
                  <button
                    type="button"
                    onClick={handleSubmit}
                    className="text-xs bg-red-500/20 hover:bg-red-500/30 text-red-300 font-semibold px-3 py-1 rounded-lg border border-red-500/40 transition-all flex-shrink-0 cursor-pointer"
                  >
                    Опитай отново
                  </button>
                </motion.div>
              )}

              {/* Име */}
              <div>
                <label htmlFor="name" className="block text-gray-300 text-sm font-medium mb-1.5 flex items-center gap-1.5">
                  <User className="w-4 h-4 text-primary-400" />
                  Вашето име <span className="text-red-400">*</span>
                </label>
                <input
                  type="text"
                  id="name"
                  name="name"
                  value={formData.name}
                  onChange={handleChange}
                  placeholder="Иван Иванов"
                  disabled={status === 'submitting'}
                  aria-invalid={!!errors.name}
                  aria-describedby={errors.name ? "name-error" : undefined}
                  className={`w-full px-4 py-3 bg-dark-700 border rounded-xl text-white placeholder-gray-500 focus:outline-none focus:ring-2 focus:ring-primary-500 transition-all ${
                    errors.name ? 'border-red-500/80 bg-red-500/5' : 'border-dark-600'
                  }`}
                />
                {errors.name && <p id="name-error" className="text-red-400 text-xs mt-1" role="alert">{errors.name}</p>}
              </div>

              {/* Email & Phone grid */}
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                {/* Email */}
                <div>
                  <label htmlFor="email" className="block text-gray-300 text-sm font-medium mb-1.5 flex items-center gap-1.5">
                    <Mail className="w-4 h-4 text-primary-400" />
                    Имейл адрес <span className="text-red-400">*</span>
                  </label>
                  <input
                    type="email"
                    id="email"
                    name="email"
                    value={formData.email}
                    onChange={handleChange}
                    placeholder="office@company.bg"
                    disabled={status === 'submitting'}
                    aria-invalid={!!errors.email}
                    aria-describedby={errors.email ? "email-error" : undefined}
                    className={`w-full px-4 py-3 bg-dark-700 border rounded-xl text-white placeholder-gray-500 focus:outline-none focus:ring-2 focus:ring-primary-500 transition-all ${
                      errors.email ? 'border-red-500/80 bg-red-500/5' : 'border-dark-600'
                    }`}
                  />
                  {errors.email && <p id="email-error" className="text-red-400 text-xs mt-1" role="alert">{errors.email}</p>}
                </div>

                {/* Phone */}
                <div>
                  <label htmlFor="phone" className="block text-gray-300 text-sm font-medium mb-1.5 flex items-center gap-1.5">
                    <Phone className="w-4 h-4 text-primary-400" />
                    Телефон <span className="text-red-400">*</span>
                  </label>
                  <input
                    type="tel"
                    id="phone"
                    name="phone"
                    value={formData.phone}
                    onChange={handleChange}
                    placeholder="0888 123 456 / 02 987 654"
                    disabled={status === 'submitting'}
                    aria-invalid={!!errors.phone}
                    aria-describedby={errors.phone ? "phone-error" : undefined}
                    className={`w-full px-4 py-3 bg-dark-700 border rounded-xl text-white placeholder-gray-500 focus:outline-none focus:ring-2 focus:ring-primary-500 transition-all ${
                      errors.phone ? 'border-red-500/80 bg-red-500/5' : 'border-dark-600'
                    }`}
                  />
                  {detectedOperator && (
                    <div className="mt-1 flex items-center gap-1 text-xs text-emerald-400">
                      <ShieldCheck className="w-3.5 h-3.5" />
                      <span>{detectedOperator.operator} ({detectedOperator.type})</span>
                    </div>
                  )}
                  {errors.phone && <p id="phone-error" className="text-red-400 text-xs mt-1" role="alert">{errors.phone}</p>}
                </div>
              </div>

              {/* Компания */}
              <div>
                <label htmlFor="company" className="block text-gray-300 text-sm font-medium mb-1.5 flex items-center gap-1.5">
                  <Building className="w-4 h-4 text-primary-400" />
                  Компания (ЕООД / ООД)
                </label>
                <input
                  type="text"
                  id="company"
                  name="company"
                  value={formData.company}
                  onChange={handleChange}
                  placeholder="Име на фирма (по избор)"
                  disabled={status === 'submitting'}
                  className="w-full px-4 py-3 bg-dark-700 border border-dark-600 rounded-xl text-white placeholder-gray-500 focus:outline-none focus:ring-2 focus:ring-primary-500 transition-all"
                />
              </div>

              {/* Съобщение */}
              <div>
                <label htmlFor="message" className="block text-gray-300 text-sm font-medium mb-1.5 flex items-center gap-1.5">
                  <MessageSquare className="w-4 h-4 text-primary-400" />
                  Съобщение или въпрос
                </label>
                <textarea
                  id="message"
                  name="message"
                  rows={3}
                  value={formData.message}
                  onChange={handleChange}
                  placeholder="Опишете вашите нужди или въпроси (по избор)"
                  disabled={status === 'submitting'}
                  className="w-full px-4 py-3 bg-dark-700 border border-dark-600 rounded-xl text-white placeholder-gray-500 focus:outline-none focus:ring-2 focus:ring-primary-500 transition-all resize-none"
                />
              </div>

              {/* Бутон за изпращане */}
              <button
                type="submit"
                disabled={status === 'submitting'}
                className="w-full px-6 py-3.5 bg-gradient-to-r from-primary-500 to-primary-600 hover:from-primary-600 hover:to-primary-700 disabled:from-gray-600 disabled:to-gray-700 text-white font-bold rounded-xl transition-all shadow-lg shadow-primary-500/20 flex items-center justify-center space-x-2 disabled:cursor-not-allowed cursor-pointer"
              >
                {status === 'submitting' ? (
                  <>
                    <Loader2 className="w-5 h-5 animate-spin" />
                    <span>Изпращане...</span>
                  </>
                ) : (
                  <>
                    <Send className="w-5 h-5" />
                    <span>Изпрати запитване</span>
                  </>
                )}
              </button>
            </form>
          )}
        </motion.div>
      </div>
    </section>
  );
}
