/**
 * Bulgarian Phone Validator & Normalizer Utility
 * Supports Mobile (+359 87/88/89/98) and Landlines (02 Sofia, 032 Plovdiv, 052 Varna, etc.)
 */

// Mobile prefixes (without country code)
const MOBILE_PREFIXES = ['87', '88', '89', '98', '99'];

// Common Landline area codes in Bulgaria
const LANDLINE_AREA_CODES = [
  '2',   // Sofia
  '32',  // Plovdiv
  '52',  // Varna
  '56',  // Bourgas
  '42',  // Stara Zagora
  '82',  // Ruse
  '64',  // Pleven
  '54',  // Shumen
  '62',  // Veliko Tarnovo
  '73',  // Blagoevgrad
  '96',  // Montana
  '34',  // Pazardzhik
  '44',  // Sliven
  '68',  // Lovech
  '94',  // Vidin
  '84',  // Razgrad
  '361', // Kardzhali
  '38'   // Haskovo
];

/**
 * Cleans phone input removing non-digit characters except leading +
 */
export const cleanPhoneString = (input) => {
  if (!input) return '';
  let str = String(input).trim();
  // Handle 00359 prefix conversion to +359
  if (str.startsWith('00359')) {
    str = '+359' + str.slice(5);
  }
  return str.replace(/[^\d+]/g, '');
};

/**
 * Normalizes any valid Bulgarian phone number into E.164 format (+359...)
 */
export const normalizeBgPhone = (input) => {
  const cleaned = cleanPhoneString(input);
  if (!cleaned) return null;

  let local = cleaned;

  if (cleaned.startsWith('+359')) {
    local = '0' + cleaned.slice(4);
  } else if (cleaned.startsWith('359')) {
    local = '0' + cleaned.slice(3);
  }

  // Ensure local starts with 0
  if (!local.startsWith('0')) {
    local = '0' + local;
  }

  // Check mobile format (087X XXXXXX, 088X XXXXXX, etc.) -> 10 digits
  if (local.length === 10 && MOBILE_PREFIXES.some(prefix => local.startsWith('0' + prefix))) {
    return '+359' + local.slice(1);
  }

  // Check Sofia landline (02 XXXXXXX) -> 9 digits
  if (local.startsWith('02') && (local.length === 8 || local.length === 9)) {
    return '+359' + local.slice(1);
  }

  // Check regional landlines (032, 052, etc.) -> 8-9 digits total
  if (local.length >= 8 && local.length <= 10) {
    const isLandline = LANDLINE_AREA_CODES.some(code => local.startsWith('0' + code));
    if (isLandline) {
      return '+359' + local.slice(1);
    }
  }

  // Generic Bulgarian fallback if 8-10 digits starting with 0
  if (/^0[1-9]\d{6,8}$/.test(local)) {
    return '+359' + local.slice(1);
  }

  return null;
};

/**
 * Validates whether string is a valid Bulgarian mobile or landline phone
 */
export const isValidBgPhone = (input) => {
  const normalized = normalizeBgPhone(input);
  return Boolean(normalized);
};

/**
 * Detects mobile operator or type (A1, Yettel, Vivacom, Landline, Unknown)
 * Bonus Value Improvement!
 */
export const identifyBgOperator = (input) => {
  const normalized = normalizeBgPhone(input);
  if (!normalized) return { operator: 'Invalid', type: 'unknown' };

  const local = '0' + normalized.slice(4); // e.g. 0888123456

  if (local.startsWith('088') || local.startsWith('087')) {
    return { operator: 'A1 Bulgaria', type: 'mobile' };
  } else if (local.startsWith('089')) {
    return { operator: 'Yettel Bulgaria', type: 'mobile' };
  } else if (local.startsWith('098') || local.startsWith('087')) {
    return { operator: 'Vivacom', type: 'mobile' };
  } else if (local.startsWith('02')) {
    return { operator: 'Sofia Landline', type: 'landline' };
  } else if (LANDLINE_AREA_CODES.some(code => local.startsWith('0' + code))) {
    return { operator: 'Regional Landline', type: 'landline' };
  }

  return { operator: 'Bulgarian Telecom', type: 'mobile' };
};

/**
 * Formats user input as they type (e.g. "+359 88 123 4567" or "088 812 3456")
 */
export const formatBgPhoneDisplay = (input) => {
  const cleaned = cleanPhoneString(input);
  if (!cleaned) return '';

  if (cleaned.startsWith('+359')) {
    const digits = cleaned.slice(4);
    if (digits.length <= 2) return `+359 ${digits}`;
    if (digits.length <= 5) return `+359 ${digits.slice(0, 2)} ${digits.slice(2)}`;
    if (digits.length <= 8) return `+359 ${digits.slice(0, 2)} ${digits.slice(2, 5)} ${digits.slice(5)}`;
    return `+359 ${digits.slice(0, 2)} ${digits.slice(2, 5)} ${digits.slice(5, 9)}`;
  }

  if (cleaned.length <= 4) return cleaned;
  if (cleaned.length <= 7) return `${cleaned.slice(0, 4)} ${cleaned.slice(4)}`;
  return `${cleaned.slice(0, 4)} ${cleaned.slice(4, 7)} ${cleaned.slice(7, 10)}`;
};
