import React, { useEffect } from 'react';

const CALENDLY_URL = import.meta.env.VITE_CALENDLY_URL || 'https://calendly.com/finansprotect/consultation';

export const loadCalendlyScript = () => {
  return new Promise((resolve) => {
    if (window.Calendly) {
      resolve(window.Calendly);
      return;
    }
    // Inject stylesheet
    if (!document.getElementById('calendly-stylesheet')) {
      const link = document.createElement('link');
      link.id = 'calendly-stylesheet';
      link.rel = 'stylesheet';
      link.href = 'https://assets.calendly.com/assets/external/widget.css';
      document.head.appendChild(link);
    }
    // Inject script
    if (!document.getElementById('calendly-script')) {
      const script = document.createElement('script');
      script.id = 'calendly-script';
      script.src = 'https://assets.calendly.com/assets/external/widget.js';
      script.async = true;
      script.onload = () => resolve(window.Calendly);
      document.body.appendChild(script);
    } else {
      resolve(window.Calendly);
    }
  });
};

export const openCalendlyModal = async (prefillData = {}) => {
  await loadCalendlyScript();
  const url = new URL(CALENDLY_URL);
  
  const prefill = {
    name: prefillData.name || localStorage.getItem('fp_lead_name') || '',
    email: prefillData.email || localStorage.getItem('fp_lead_email') || '',
    customAnswers: {
      a1: prefillData.company || localStorage.getItem('fp_lead_company') || '',
      a2: prefillData.phone || ''
    }
  };

  if (window.Calendly && typeof window.Calendly.initPopupWidget === 'function') {
    window.Calendly.initPopupWidget({
      url: url.toString(),
      prefill
    });
  } else {
    window.open(url.toString(), '_blank');
  }

  // Trigger custom event for telemetry tracking
  if (typeof window !== 'undefined') {
    window.dispatchEvent(new CustomEvent('fp_calendly_opened', { detail: prefill }));
  }
};

export default function CalendlyModalButton({ className, buttonText = "Запазете 1-on-1 Консултация", prefill = {} }) {
  useEffect(() => {
    loadCalendlyScript();
  }, []);

  return (
    <button
      type="button"
      onClick={() => openCalendlyModal(prefill)}
      className={className || "px-6 py-3 bg-gradient-to-r from-emerald-500 to-teal-600 hover:from-emerald-600 hover:to-teal-700 text-white font-semibold rounded-xl shadow-md transition-all flex items-center gap-2 cursor-pointer"}
    >
      <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M8 7V3m8 4V3m-9 8h10M5 21h14a2 2 0 002-2V7a2 2 0 002-2H5a2 2 0 00-2 2v12a2 2 0 002 2z" />
      </svg>
      <span>{buttonText}</span>
    </button>
  );
}
