/**
 * Lightweight Client Security Fingerprinting Utility
 * Generates an internal non-invasive canvas hash & browser metrics for fraud scoring.
 */

export const generateDeviceFingerprint = () => {
  if (typeof window === 'undefined' || typeof document === 'undefined') {
    return { hash: 'server_env', confidence: 1.0 };
  }

  try {
    const canvas = document.createElement('canvas');
    canvas.width = 200;
    canvas.height = 50;
    const ctx = canvas.getContext('2d');
    
    if (ctx) {
      ctx.textBaseline = 'top';
      ctx.font = '14px Arial';
      ctx.textBaseline = 'alphabetic';
      ctx.fillStyle = '#f60';
      ctx.fillRect(125, 1, 62, 20);
      ctx.fillStyle = '#069';
      ctx.fillText('FinansProtect Security Canvas 1.0', 2, 15);
      ctx.fillStyle = 'rgba(102, 204, 0, 0.7)';
      ctx.fillText('FinansProtect Security Canvas 1.0', 4, 17);
    }

    const dataUrl = canvas.toDataURL();
    let hash = 0;
    for (let i = 0; i < dataUrl.length; i++) {
      const char = dataUrl.charCodeAt(i);
      hash = (hash << 5) - hash + char;
      hash |= 0;
    }

    const screenMetrics = `${window.screen?.width || 0}x${window.screen?.height || 0}x${window.screen?.colorDepth || 0}`;
    const userAgent = navigator.userAgent || '';
    const language = navigator.language || '';
    const timezone = Intl.DateTimeFormat().resolvedOptions().timeZone || '';

    return {
      hash: `fp_fp_${Math.abs(hash).toString(16)}`,
      screenMetrics,
      language,
      timezone,
      botScore: navigator.webdriver ? 0.99 : 0.01,
      userAgent
    };
  } catch (err) {
    return { hash: 'fp_fp_fallback', botScore: 0.1 };
  }
};
