/**
 * Unified Telemetry & Conversion Analytics Module
 * Dual-dispatch: Client-side (Google Analytics / FB Pixel) + Server-side Fallback
 */

export const trackEvent = async (eventName, payload = {}) => {
  const timestamp = new Date().toISOString();
  const fullPayload = {
    event: eventName,
    ...payload,
    timestamp,
    url: typeof window !== 'undefined' ? window.location.href : '',
    userAgent: typeof navigator !== 'undefined' ? navigator.userAgent : ''
  };

  // 1. Dispatch custom DOM event for internal listeners
  if (typeof window !== 'undefined') {
    window.dispatchEvent(new CustomEvent('fp_telemetry_event', { detail: fullPayload }));
  }

  // 2. Client Google Analytics (gtag)
  if (typeof window !== 'undefined' && typeof window.gtag === 'function') {
    try {
      window.gtag('event', eventName, payload);
    } catch (e) {}
  }

  // 3. Client Facebook Pixel (fbq)
  if (typeof window !== 'undefined' && typeof window.fbq === 'function') {
    try {
      window.fbq('trackCustom', eventName, payload);
    } catch (e) {}
  }

  // 4. Server-Side Dual Dispatch Fallback (Bypasses Client Ad-Blockers) (Bonus Value!)
  try {
    fetch('/api/telemetry', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(fullPayload)
    }).catch(() => {});
  } catch (err) {}

  return fullPayload;
};
